export function PartialLoading({
  loadedPortion = "{{loadedPortion}}",
  showLabels = {{showLabels}},
  accent = "{{accent}}",
}) {
  const loadedBody = loadedPortion === "half" || loadedPortion === "most";
  const loadedFooter = loadedPortion === "most";
  const pending = { background: "repeating-linear-gradient(45deg, #24143010 0 8px, transparent 8px 16px)" };
  const block = { height: 34, borderRadius: 8, marginBottom: 8, display: "flex", alignItems: "center", justifyContent: "center", color: "#241430", fontWeight: 600 };
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430aa" }}>
      <div style={{ ...block, background: accent }}>{showLabels && "header"}</div>
      <div aria-hidden={!loadedBody} style={{ ...block, ...(loadedBody ? {} : pending) }}>{showLabels && !loadedBody && "pending"}</div>
      <div aria-hidden={!loadedFooter} style={{ ...block, ...(loadedFooter ? {} : pending) }}>{showLabels && !loadedFooter && "pending"}</div>
      <p role="status" aria-live="polite" style={{ margin: "6px 0 0", textTransform: "capitalize" }}>{loadedPortion} loaded &mdash; the rest streams in as it becomes ready</p>
    </div>
  );
}
